import sys

def main():
    import sys
    input = sys.stdin.read().splitlines()
    idx = 0
    results = []
    t = int(input[idx])
    idx += 1
    for _ in range(t):
        n, q = map(int, input[idx].split())
        s = input[idx + 1]
        idx += 2
        for _ in range(q):
            l_i, r_i = map(int, input[idx].split())
            idx += 1
            sub = s[l_i - 1:r_i]
            if len(sub) < 2:
                results.append("NO")
            else:
                found = False
                for i in range(len(sub)):
                    for j in range(i + 2, len(sub)):
                        if sub[i] == sub[j]:
                            found = True
                            break
                    if found:
                        break
                results.append("YES" if found else "NO")
    print("\n".join(results))

main()
